import{z as n,x as s,o as E,c as m,q as A,j as o,D as e,d as r,s as B,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"Mirrlees 最优所得税","description":"","frontmatter":{"title":"Mirrlees 最优所得税","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mirrlees-optimal-tax.md","filePath":"econ/mirrlees-optimal-tax.md","lastUpdated":1791413859000}'),p={name:"econ/mirrlees-optimal-tax.md"};function d(c,a,f,h,F,u){const i=s("Mermaid");return E(),m("div",null,[a[2]||(a[2]=A('<h1 id="mirrlees-最优所得税" tabindex="-1">Mirrlees 最优所得税 <a class="header-anchor" href="#mirrlees-最优所得税" aria-label="Permalink to &quot;Mirrlees 最优所得税&quot;">​</a></h1><div class="epigraph"><p>政府看不见能力，只看得见收入；最优税率不是伦理口号，而是激励约束下「再分配收益等于行为损失」的一阶条件。</p><footer>—— Mirrlees, An Exploration in the Theory of Optimum Income Taxation, RES 1971；Saez, Using Elasticities to Derive Optimal Income Tax Rates, RES 2001；Stern, Welfare Weights and the Elasticity of the Marginal Valuation of Income, 1977</footer></div><p><a href="/econ/local-fiscal-transfers">上一课</a>把多级政府写成代理与承诺问题：飞纸与软预算是激励失败，地方隐性债最后并入主权 \\(b\\)。「政府做什么」课序收在那里；本课起进入加深课序，税制的设计问题往深处走一层。<a href="/econ/income-tax-incentives">所得税与激励</a>已给出充分统计的弹性语言，微观主干<a href="/econ/mirrlees-income">最优所得税</a>已立激励相容的结构。本课把两者接上：从弹性直接推出最优税率，并把顶端零税率的直觉与争议讲清。后三课沿归宿、无谓损失、碳定价走完这条加深线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>能力 \\(n\\) 私有信息，收入 \\(y=nl\\)，只观察得到 \\(y\\)。对 \\(n\\) 征总额税做不到，对 \\(y\\) 征税必然扭曲劳动——缺口是：扭曲应放在哪些收入段、放多深。把 \\(T(y)\\) 读成机制：高类型可以压低劳动去模仿低类型的 \\(y\\)，激励相容迫使计划者给高类型留信息租金；租金随类型从底部积出来，再分配的每一分钱都在「租金」与「扭曲」之间定价。主干课已经说了答案是弹性、密度、权重三个词；加深要问的是三者怎么精确组装成一个税率，以及每个部件在什么方向上移动它。</p><h3 id="从三个词到一个公式" tabindex="-1">从三个词到一个公式 <a class="header-anchor" href="#从三个词到一个公式" aria-label="Permalink to &quot;从三个词到一个公式&quot;">​</a></h3><p>在收入 \\(z\\) 处把边际税率提高 \\(\\mathrm{d}\\tau\\)：高于 \\(z\\) 的人各多缴约 \\(z\\,\\mathrm{d}\\tau\\)，这是机械收入；他们的应税收入按补偿弹性收缩，行为损失随弹性走；福利上，一元对高收入者的价值低于对社会（权重差）。三项相抵，一阶条件给出 Saez 2001 的形式：</p> \\[\\frac{\\tau(z)}{1-\\tau(z)}=\\frac{1}{e}\\,\\bigl(1-g(z)\\bigr)\\,\\frac{1-F(z)}{z\\,f(z)} . \\]<p>\\(e\\) 是应税收入的补偿弹性，\\(g(z)\\) 是 \\(z\\) 处一美元的社会边际价值（归一到国库一元），\\((1-F)/zf\\) 是局部 Pareto 风险率的倒数——顶端还有多厚。顶端段收敛为 \\(\\tau/(1-\\tau)=\\frac{1}{e}(1-g)/a\\)，\\(a\\) 是 Pareto 参数。</p><p><span class="marginnote">代入一组数看看量级：取 \\(e=0.5\\)、\\(g=0.4\\)、顶端 Pareto 参数 \\(a=1.5\\)，则 \\(1/e=2\\)、\\((1-g)=0.6\\)、\\((1-F)/zf\\approx 1/a=0.67\\)，三项相乘 \\(\\approx 0.8\\)，解出 \\(\\tau\\approx 44\\%\\)。初学者常以为最优税率是「拍出来的政治数字」，其实它就是三个可估计对象（弹性、权重、尾厚）的乘法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公式先过一遍代入检验。功利基准 \\(g=1\\)：右边为零，最优边际税为零——再分配全部来自 \\(g(z)\\lt 1\\) 的段落，权重不是装饰。弹性：\\(e\\) 越大楔子越贵，这是 <a href="/econ/ramsey-optimal-commodity-tax">Ramsey 商品税</a>逆弹性在技能维度上的亲戚，但这里的「税基」是收入分布本身。密度：尾越厚，楔子上方的机械税基越大，越值得在那一带压税率。权重：Stern 1977 把 \\(g(z)\\) 参数化成边际评价对收入的弹性，规范立场从形容词变成可争论的数字——<a href="/econ/redistribution-efficiency">再分配与效率代价</a>说「权重与弹性是两件东西」，公式正是两件东西的乘法。生产侧不另设楔子：所得税扭曲留在消费与劳动，生产效率由 Diamond–Mirrlees 1971 保证，<a href="/econ/ramsey-optimal-commodity-tax">商品税课</a>已用其一半。</p>',12)),(E(),o(l,null,{default:e(()=>[B(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20LFT%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%A4%9A%E7%BA%A7%E8%B4%A2%E6%94%BF%E4%B8%8E%E6%95%91%E5%8A%A9%E9%A2%84%E6%9C%9F%22%5D%20--%3E%20DEEP%5B%22%E5%8A%A0%E6%B7%B1%E8%AF%BE%E5%BA%8F%3A%20%E7%A8%8E%E5%88%B6%E8%AE%BE%E8%AE%A1%E8%B5%B0%E6%B7%B1%22%5D%0A%20%20DEEP%20--%3E%20IC%5B%22%E8%83%BD%E5%8A%9B%E4%B8%8D%E5%8F%AF%E8%A7%81%3A%20%E9%9D%9E%E7%BA%BF%E6%80%A7%20T(y)%20%2B%20%E6%BF%80%E5%8A%B1%E7%9B%B8%E5%AE%B9%22%5D%0A%20%20IC%20--%3E%20RENT%5B%22%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%E4%BB%8E%E5%BA%95%E9%83%A8%E7%A7%AF%E5%87%BA%22%5D%0A%20%20RENT%20--%3E%20SAEZ%5B%22%E5%BC%B9%E6%80%A7%20x%20%E6%9D%83%E9%87%8D%20x%20%E5%B0%BE%E5%8E%9A%20%E7%9A%84%E7%A8%8E%E7%8E%87%E5%85%AC%E5%BC%8F%22%5D%0A%20%20SAEZ%20--%3E%20TOP%5B%22%E9%A1%B6%E7%AB%AF%E9%9B%B6%E7%A8%8E%E7%8E%87%E4%B8%8E%E5%8E%9A%E5%B0%BE%E4%BA%89%E8%AE%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"零顶端税率是 Mirrlees 1971 的边界结果：若最高类型有界，对最后一人征边际税只扭曲他的劳动、没有任何模仿需要阻止，故 \\(T'(y_{\\max})=0\\)；在 Saez 公式里它就是 \\(F\\to 1\\) 时右边趋零。争议在于现实分布：顶端收入近似 Pareto 且无清楚上界，\\(F\\to 1\\) 只在渐近意义成立，厚尾把 \\((1-F)/zf\\) 顶在 \\(1/a\\) 附近，于是接近顶端的 \\(\\tau\\) 可以显著为正。把「顶端零税率」读成最高档法定税率应为零，是拿有限支撑的构造对无限厚尾的政策——主干课的警告在此落成机制。",-1)),(E(),o(l,null,{default:e(()=>[B(i,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20LR%0A%20%20A1%5B%22%E5%81%87%E8%AE%BE%EF%BC%9A%E6%9C%80%E9%AB%98%E6%8A%80%E8%83%BD%E6%9C%89%E7%95%8C%22%5D%20--%3E%20A2%5B%22F%20%E8%B6%8B%E4%BA%8E%201%EF%BC%9A%E9%A1%B6%E7%AB%AF%E4%B9%8B%E4%B8%8A%E6%97%A0%E4%BA%BA%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E9%A1%B6%E7%AB%AF%E8%BE%B9%E9%99%85%E7%A8%8E%20T'%20%3D%200%22%5D%0A%20%20B1%5B%22%E7%8E%B0%E5%AE%9E%EF%BC%9A%E6%94%B6%E5%85%A5%E8%BF%91%E4%BC%BC%20Pareto%20%E5%8E%9A%E5%B0%BE%22%5D%20--%3E%20B2%5B%22(1-F)%2Fzf%20%E9%A1%B6%E5%9C%A8%201%2Fa%20%E9%99%84%E8%BF%91%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E6%8E%A5%E8%BF%91%E9%A1%B6%E7%AB%AF%E7%9A%84%E6%9C%80%E4%BC%98%E7%A8%8E%E7%8E%87%E4%BB%8D%E6%98%BE%E8%91%97%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20A3%20--%3E%20Q%5B%22%E4%BA%89%E8%AE%AE%EF%BC%9A%E7%94%A8%E5%93%AA%E7%A7%8D%E6%94%AF%E6%92%91%E8%AF%BB%E6%94%BF%E7%AD%96%22%5D%0A%20%20B3%20--%3E%20Q%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">「尾厚」可以想象成收入阶梯越往上台阶越长：顶端 1% 内部从 50 万元到 500 万元还有十倍空间，「最顶端」不是一个点而是一大片人。只要这一片还存在，抬高他们边际税率仍能从大片税基上收钱——这就是为什么厚尾让「顶端零税率」迟迟不登场。</span></p><p><span class="marginnote">信息租金的反面是扭曲：底部参与弹性大，最优安排常在低收入段给低边际税甚至补贴，把租金付在「让人进场」上，而在中高收入段收楔子。两端的税率形状由不同的弹性驱动，不能共用一个数字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>公式里的 \\(e\\) 是应税收入弹性，避税、申报时点、收入定义都算进行为，工时弹性会低估税基反应、高估最优税；extensive 边际另写一阶条件。bunching、动态与资本收入不在此。\\(g\\) 是规范输入，弹性估计搬不走制度。</p><p><span class="marginnote">「补偿弹性」翻译成大白话：只算替代效应、把收入效应（涨价让你更穷这件事）剔除后，税后回报每涨 1%，你愿意多挣百分之几。\\(e=0.5\\) 就是边际回报提高 10%、应税收入增加 5%。初学者容易把非补偿（毛）弹性直接代入公式——那样会把「因税变穷所以多干活」的收入效应错算成行为损失。</span>后课默认：谈最优税率先指认公式三件套的数值来源；下一课把楔子的另一层——法定开票与经济承担——分开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>能力私有信息下，所得税是激励相容机制；信息租金是再分配的影子价格。</li><li>最优边际税率 = 行为损失与再分配收益的一阶条件：弹性、福利权重、局部尾厚三件套。</li><li>顶端零税率来自 \\(F\\to 1\\)；厚 Pareto 尾让接近顶端的税率仍高，争议在支撑假设。</li><li>公式的弹性是应税收入弹性，避税通道必须算进行为。</li><li>出处：Mirrlees 1971；Saez 2001；Stern 1977；Ramsey 1927；Diamond and Mirrlees 1971。</li></ul>',7))])}const T=n(p,[["render",d]]);export{x as __pageData,T as default};
